import{_ as i,o as a,c as r,a3 as l}from"./chunks/framework.DACwFHq9.js";const h=JSON.parse('{"title":"LLM Provider Adapter 多端共享收口记录","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/llm-provider-adapter-sharing-investigation.md","filePath":"Plan/llm-provider-adapter-sharing-investigation.md","lastUpdated":1785283012000}'),o={name:"Plan/llm-provider-adapter-sharing-investigation.md"};function t(d,e,n,c,p,s){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="llm-provider-adapter-多端共享收口记录" tabindex="-1">LLM Provider Adapter 多端共享收口记录 <a class="header-anchor" href="#llm-provider-adapter-多端共享收口记录" aria-label="Permalink to &quot;LLM Provider Adapter 多端共享收口记录&quot;">​</a></h1><blockquote><p>状态：代码与自动化验收已完成；仅保留真实 Tauri 性能观测及 Android/iOS 真机验收</p><p>最后更新：2026-07-28</p><p>当前架构：<a href="./../architecture/llm-apis-architecture"><code>docs/architecture/llm-apis-architecture.md</code></a></p></blockquote><h2 id="_1-当前结论" tabindex="-1">1. 当前结论 <a class="header-anchor" href="#_1-当前结论" aria-label="Permalink to &quot;1. 当前结论&quot;">​</a></h2><p>桌面端与移动端已经统一使用 <code>@aiohub/llm-core</code> 的纯 TypeScript Provider Core，平台差异由 Transport、鉴权、配置和应用 Facade 承担。原调查中的共享可行性、Provider 迁移和 Rust 边界设计均已落地，不再保留逐批施工日志。</p><p>尚未关闭的只有依赖真实 WebView、操作系统调度或设备生命周期的人工观测；它们不阻塞已完成的代码迁移。</p><h2 id="_2-已落地架构" tabindex="-1">2. 已落地架构 <a class="header-anchor" href="#_2-已落地架构" aria-label="Permalink to &quot;2. 已落地架构&quot;">​</a></h2><h3 id="_2-1-共享-core" tabindex="-1">2.1 共享 Core <a class="header-anchor" href="#_2-1-共享-core" aria-label="Permalink to &quot;2.1 共享 Core&quot;">​</a></h3><p><code>packages/llm-core</code> 提供：</p><ul><li>canonical <code>LlmRequest</code>、<code>LlmResponse</code>、媒体与异步任务 DTO；</li><li><code>ProviderAdapter</code>、<code>WireRequest</code>、<code>WireResponse</code>、<code>LlmTransport</code> 和 Observer 契约；</li><li>增量 SSE/JSONL 分帧与 Provider 流式 Decoder；</li><li>JSON、multipart 和顶层请求体的显式 <code>LocalFileRef</code>；</li><li>聊天、Embedding、模型列表、同步媒体与异步媒体任务的请求构建和响应归一化。</li></ul><p>共享包不导入 Vue、Pinia、Tauri、应用 Store 或 UI 模块，也不直接执行网络请求。</p><h3 id="_2-2-provider-覆盖" tabindex="-1">2.2 Provider 覆盖 <a class="header-anchor" href="#_2-2-provider-覆盖" aria-label="Permalink to &quot;2.2 Provider 覆盖&quot;">​</a></h3><p>桌面和移动的重复 builder、parser 与流循环已经收敛到共享实现，覆盖：</p><ul><li>OpenAI-Compatible / Chat Completions；</li><li>OpenAI Responses；</li><li>Anthropic Messages；</li><li>Gemini Developer API、Vertex Google 与 Vertex Anthropic；</li><li>Cohere、DeepSeek/OneAPI、Hugging Face 等兼容路径；</li><li>OpenAI、Gemini、Cohere、Vertex Embedding；</li><li>图片、音频、模型列表，以及视频/音乐异步任务。</li></ul><p>应用 Facade 继续负责 Profile、KeyManager、自定义 Header、错误本地化、Inspector、回调兼容和模型元数据写入。</p><h3 id="_2-3-平台-transport-与-rust-边界" tabindex="-1">2.3 平台 Transport 与 Rust 边界 <a class="header-anchor" href="#_2-3-平台-transport-与-rust-边界" aria-label="Permalink to &quot;2.3 平台 Transport 与 Rust 边界&quot;">​</a></h3><ul><li>桌面 Transport 复用现有超时、取消、Inspector、TLS/HTTP 选项和异步序列化入口。</li><li>Rust 代理提供 <code>/proxy/raw</code> 与 <code>/proxy/json-expand</code>，受控展开三类 <code>LocalFileRef</code>。</li><li><code>reqwest::Client</code> 按稳定网络策略复用；代理使用 capability token、严格 Origin/CORS 和敏感 Header/日志保护。</li><li>移动 Transport 保留移动网络插件与应用生命周期边界，但遵循同一 Wire 合约。</li><li>Provider 语义留在 TypeScript Core；没有性能证据时不下沉到 Rust。</li></ul><h2 id="_3-自动化验收结论" tabindex="-1">3. 自动化验收结论 <a class="header-anchor" href="#_3-自动化验收结论" aria-label="Permalink to &quot;3. 自动化验收结论&quot;">​</a></h2><p>已完成的自动化范围包括：</p><ul><li>Provider payload、Header、端点、参数和错误语义；</li><li>多模态、tool call/tool result、reasoning artifact 和 usage；</li><li>UTF-8 跨 chunk、逐字节切块、CRLF/LF、粘包、流末尾、取消和流中断；</li><li>状态/Header/原始字节流保真；</li><li>JSON、multipart、顶层文件引用与二进制响应；</li><li>桌面、移动、共享包类型检查与生产构建；</li><li>桌面与移动 Transport 的组合约测试。</li></ul><p>历史测试数量只代表当时快照，不再作为当前完成度依据。后续改动按仓库现有脚本重新验证。</p><h2 id="_4-仅剩人工验收" tabindex="-1">4. 仅剩人工验收 <a class="header-anchor" href="#_4-仅剩人工验收" aria-label="Permalink to &quot;4. 仅剩人工验收&quot;">​</a></h2><h3 id="_4-1-桌面真实-tauri-性能观测" tabindex="-1">4.1 桌面真实 Tauri 性能观测 <a class="header-anchor" href="#_4-1-桌面真实-tauri-性能观测" aria-label="Permalink to &quot;4.1 桌面真实 Tauri 性能观测&quot;">​</a></h3><p>使用可控上游分别发送大文本、嵌套 JSON FileRef、顶层文件和 multipart 媒体，记录：</p><ul><li>WebView 与 Rust 峰值内存；</li><li>主线程阻塞、序列化次数和 TTFB；</li><li>冷/暖请求差异；</li><li>流式首 chunk 是否在完整响应结束前交付。</li></ul><p>若结果没有显示共享 TypeScript Core 或 WebView 边界造成可感知问题，不继续把 Provider 解析下沉 Rust。</p><h3 id="_4-2-android-ios-真机" tabindex="-1">4.2 Android / iOS 真机 <a class="header-anchor" href="#_4-2-android-ios-真机" aria-label="Permalink to &quot;4.2 Android / iOS 真机&quot;">​</a></h3><p>至少各使用一台真机，记录系统与 WebView 版本，验证：</p><ul><li>长流逐段交付和用户取消；</li><li>三类 FileRef 请求；</li><li>前后台切换后的继续、明确失败或系统终止行为；</li><li>大请求内存和超时边界。</li></ul><p>移动真机结果写入移动端验收记录；协议错误必须回到共享 Core 补自动化测试，不能用“设备差异”豁免。</p><h2 id="_5-完成口径" tabindex="-1">5. 完成口径 <a class="header-anchor" href="#_5-完成口径" aria-label="Permalink to &quot;5. 完成口径&quot;">​</a></h2><ul><li>桌面运行态数据已记录并完成是否需要继续优化的决策；</li><li>Android/iOS 真机结果已有明确环境和结论；</li><li>发现的问题已回写架构或对应模块计划。</li></ul><p>完成后删除本文；长期边界继续由 <code>docs/architecture/llm-apis-architecture.md</code> 维护。</p>',32)])])}const m=i(o,[["render",t]]);export{h as __pageData,m as default};
